  "assets": [
    {
      "asset": "product",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "on_sale = false（写在指标 expression 内，不写 on_sale <> false，以免漏掉 on_sale IS NULL 的行）"
  ],
  "grain": "product（SKU 粒度存量快照，无分组，单行汇总）",
  "limit": 1,
  "metrics": [
    {
      "caliber": "已下架的存量商品数：COUNT(*) WHERE on_sale = false（过滤条件写在 expression 里，非域级谓词）；与 on_sale_product_cnt 互补，但两者相加 ≠ product_cnt（on_sale IS NULL 的行两边都不计）。时间基准=current，与任何时间区间无关。",
      "name": "off_sale_product_cnt"
    }
  ],
  "order_by": [],
  "output_columns": [
    "off_sale_product_cnt"
  ],
  "time_range": {
    "end": null,
    "start": null
  }
}

